head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenTpCD = "";
scwin.vBzProcsNo = "";
scwin.vIsurCd = "";
// 세션정보를 얻기위한 함수사용

scwin.trsIdx; // insert, update 구분
scwin.rowPos;
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID());
scwin.vSPOT_ISU_TRD_MKT_TP_CD;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        $c.libRoundPanel.PanelToGroupBox(panel_Item);

        /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제

        buttonSet.setInsertStatus();
        const sbmOptions = {
            id : "sbm_dts_Isu",
            action : "/gauceSystemierAdaptor.do",
            ref : "",
            target : "dts_Isu=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
            txb_ISU_CD.focus();
            return;
        } else {
            scwin.initItem();
            await scwin.bfprc();
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name img_ISU_NM_onclick
 * @description img_ISU_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_NM_onclick = function() {
    try {
        fn_GetPar = scwin.getParIsuCd;
        fn_SetPar = scwin.setParIsuCd;
        $c.lc.fn_PopFindIsu(scwin.fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05702.img_ISU_NM_onclick" });
    }
};

/**
 * @method
 * @name img_CHD_DD_onclick
 * @description img_CHD_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_CHD_DD_onclick = function() {
    try {
        popUpCalendar2(edt_CHG_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05702.img_CHD_DD_onclick" });
    }
};

/**
 * @method
 * @name dts_BZ_CHECK_OnLoadError
 * @description dts_BZ_CHECK 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_BZ_CHECK_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_BZ_CHECK);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.dts_BZ_CHECK_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadError
 * @description dts_Mst 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Mst_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Mst);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.dts_Mst_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Isu_OnLoadError
 * @description dts_Isu 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Isu_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Isu);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.dts_Isu_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Mst_OnLoadCompleted
 * @description dts_Mst 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Mst_OnLoadCompleted = function(rowcount) {
    try {
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        } else {
            if ($c.ut.cGetToday("yyyymmdd") < edt_CHG_DD.getValue()) {
                buttonSet.setUpdateStatus();
            } else {
                buttonSet.setErrorStatus();
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05702.dts_Mst_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        if (scwin.vBzProcsNo === "") {
            buttonSet.setInsertStatus();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05702.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name grd_List_OnClick
 * @description grd_List 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnClick = async function(row, colid) {
    try {
        await scwin.readSync(row);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.grd_List_OnClick" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.initItem();
        await scwin.listSync();
        await scwin.bfprc();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        $c.lc.fn_alertMsg('F');
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_New_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_New_onclick = async function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            await $c.win.alert("[종목]을 선택하세요.");
            txb_ISU_CD.focus();
            return;
        } else {
            scwin.initItem();
            await scwin.bfprc();
            await scwin.listSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05702.btn_New_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name bfprc
 * @description 종목코드 선택시 변경전 행사가격을 가져온다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bfprc = async function() {
    url += "?SCREN_ID=" + "ULDSTF05702.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchSWPrclist&inputMessageId=CHGLIST_PRC_INOUT&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/Listing.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name listSync
 * @description 종목코드선택시 행사가격 조정 내역 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    url += "?SCREN_ID=" + "ULDSTF05702.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchChgList&DIV_IDX=10&ISU_CD=" + txb_ISU_CD.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/Listing.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name readSync
 * @description 그리드  더블 클릭시 조회
 * @param {Number} row 행 인덱스
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function(row) {
    scwin.vBzProcsNo = dts_List.getCellData(row, "BZ_PROCS_NO");
    url += "?SCREN_ID=" + "ULDSTF05702.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=searchChgList&DIV_IDX=12&BZ_PROCS_NO=" + scwin.vBzProcsNo;
    const sbmOptions = {
        id : "sbm_dts_Mst",
        action : "/Listing.do",
        ref : "",
        target : "dts_Mst=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    if (scwin.trsIdx === '1') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (scwin.trsIdx === '2') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    } else if (scwin.trsIdx === '3') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    }
    dts_Mst.setCellData(1, "ISUR_CD", scwin.vIsurCd);
    dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
    dts_Mst.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
    dts_Mst.setCellData(1, "BFCHG_EXER_PRC", edt_BFCHG_EXER_PRC.getValue());
    dts_Mst.setCellData(1, "AFCHG_EXER_PRC", edt_AFCHG_EXER_PRC.getValue());
    trs_Save.KeyName = "toinb_dataid4";
    // [전환검토] trs_Save.Parameters → 동적 파라미터(필요 시 sbmOptions 에 반영)
    // const sbmParams = {
    //     TRS_IDX : scwin.trsIdx,
    //     BZ_PROCS_NO : scwin.vBzProcsNo,
    //     COUNT : "1",
    //     LIST_BZ_TP_CD : LIST_BZ_TP_CD_150 + ",DIV_IDX[0]=" + DIV_IDX_CHGLIST_SWPRC
    // };
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/Listing.do",
        ref : "dts_Mst",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsuCd
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsuCd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = ""; // 코드값을 포함할 컨트롤
    // arrPar[1] = getObjectValue(txb_SearchNm);    // 명칭값을 포함할 컨트롤
    arrPar[1] = ""; // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    //
    // ********************************************************************
    arrPar, length;
};

/**
 * @method
 * @name setParIsuCd
 * @description 종목코드 선택시
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsuCd = async function(arrPar) {
    const dbClickYn = arrPar[0].DBCLICKYN;
    if (dbClickYn === "Y") {
        txb_ISU_CD.setValue(arrPar[0].ISU_CD);
        txb_ISU_NM.setValue(arrPar[0].ISU_KOR_NM);
        scwin.vSPOT_ISU_TRD_MKT_TP_CD = arrPar[0].SPOT_ISU_TRD_MKT_TP_CD;
        scwin.vIsurCd = arrPar[0].ISUR_CD;
        scwin.initItem();
        await scwin.listSync(); // 행사가격 조정내역
        await scwin.bfprc(); // 변경전 행사가격

    }
};

/**
 * @method
 * @name initItem
 * @description init Item 처리
 * @returns {void}
 * @hidden N
 */
scwin.initItem = function() {
    buttonSet.setInsertStatus();
    dts_Isu.removeAll();
    dts_Isu.insertRow();
    dts_Mst.removeAll();
    dts_Mst.insertRow();
    scwin.vBzProcsNo = ""; // 초기화

};

/**
 * @method
 * @name getListBzTpCd
 * @description get List Bz Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.getListBzTpCd = function() {
    let VListBzTpCd = "";
    if (scwin.fr_SecuGrpId === SECUGRP_ID_SW) {
        // SW : 신주인수권증권
        VListBzTpCd = LIST_BZ_TP_CD_150; // 상장업무구분코드 : 150 - 신주인수권증권 행사가격

    }
    return VListBzTpCd;
};

/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    const vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISU_CD.getValue() === "") {
        await $c.win.alert("[종목코드]를 선택하세요.");
        txb_ISU_CD.focus();
        return false;
    }
    if (edt_CHG_DD.getValue() === "") {
        await $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if ($c.ut.cGetToday("yyyymmdd") >= edt_CHG_DD.getValue()) {
        await $c.win.alert("[변경상장일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (txb_CHG_RSN_CONTN.getValue() === "") {
        await $c.win.alert("[변경사유]을 입력하세요.");
        txb_CHG_RSN_CONTN.focus();
        return false;
    }
    if (!$c.stf.checkMaxLength(txb_CHG_RSN_CONTN, 1000, "변경사유")) return false;
    if (edt_AFCHG_EXER_PRC.getValue() === "") {
        await $c.win.alert("[변경후 행사가격(원)]을 입력하세요.");
        edt_AFCHG_EXER_PRC.focus();
        return false;
    }
    if (!$c.lc.fn_check_bz_doubleinput(dts_BZ_CHECK, txb_ISU_CD.getValue(), edt_CHG_DD.getValue(), dts_Mst.getCellData(1, "BZ_PROCS_NO"), scwin.getListBzTpCd())) {
        return false;
    }
    return true;
};

/**
 * @method
 * @name save
 * @description 저장
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.save = async function() {
    scwin.trsIdx = TRS_IDX_INSERT;
    if (!await scwin.checkForm()) return;
    if (!$c.lc.fn_isProcess('I')) return;
    scwin.vBzProcsNo = await $c.stf.getNewBzProcNo(dts_BzProcsNo);
    if (scwin.vBzProcsNo.length !== 14) {
        await $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
    } else {
        dts_Mst.setCellData(1, "BZ_PROCS_NO", scwin.vBzProcsNo);
        // alert('[dts_Mst]'+dts_Mst.text);
        await scwin.trs();
    }
};

/**
 * @method
 * @name update
 * @description update 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.update = async function() {
    scwin.trsIdx = TRS_IDX_UPDATE;
    if (!await scwin.checkForm()) return;
    if (!$c.lc.fn_isProcess('U')) return;
    await scwin.trs();
};

/**
 * @method
 * @name delete
 * @description delete 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.delete = async function() {
    if (!$c.lc.fn_isProcess('D')) return;
    buttonSet.setDeleteStatus(); // buttonSet에 CRUD상태를 저장하여 이용하는 사례, TR의 응답event에서 사용.

    scwin.trsIdx = TRS_IDX_DELETE;
    await scwin.trs();
};
